// Define `int` as an alias for `isize` so that we can use the requested signature.
type int = isize;

/// Returns 1.0 if i == j, otherwise 0.0.
fn diag_val(i: int, j: int) -> f64 {
    if i == j { 1.0 } else { 0.0 }
}

/// Constructs and returns an n × n identity matrix of `f64`.
fn identity(n: usize) -> Vec<Vec<f64>> {
    let mut matrix = Vec::with_capacity(n);
    for i in 0..n {
        let mut row = Vec::with_capacity(n);
        for j in 0..n {
            // Convert the usize indices to `int` to call diag_val.
            row.push(diag_val(i as int, j as int));
        }
        matrix.push(row);
    }
    matrix
}

